import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, useWatched, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** Whether the signed-in user watches the person (yes/no), and a button that toggles it. A watcher is told
 *  (server side) when one of the person's claims is settled, approved or re-settled. */
function PersonWatch({ sheetId, personId }: { sheetId: string; personId: number }) {
  const watchedIds = useWatched(sheetId);
  const queryClient = useQueryClient();
  const watched = (watchedIds.data ?? []).includes(personId);

  const watch = useMutation({
    mutationFn: (body: { watch: boolean }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/watch`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, watch.reset);

  return (
    <td>
      <span data-testid="person-watched">{watched ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-watch"
        disabled={watch.isPending || !watchedIds.isSuccess}
        onClick={() => {
          announce();
          watch.reset();
          watch.mutate({ watch: !watched });
        }}
      >
        {watched ? 'Unwatch' : 'Watch'}
      </button>
      {watch.isError && <span data-testid="person-error">{watch.error.message}</span>}
    </td>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 55, Component: () => <th>Watched</th> }),
  PersonCells.fill({ order: 55, Component: PersonWatch }),
];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
import { claimsKey, type Claim } from '../claims/useClaims';
import { useShowRetired } from '../retire/useShowRetired';
import { GRADES, fetchPeople, peopleKey, usePeople, type Person } from './usePeople';

/** The sheet's people: a form that adds a person, or edits one when their editor is open, and the
 *  list of everyone in the order they were added (retired people only when "show retired" is on), each
 *  with the grade in force on the sheet's today. An edit records the form's grade from its from-date
 *  (blank: the sheet's today); the first grade a person is given applies from the beginning of time.
 *  A person may have their own terms (days; blank for none), shown on their row: a claim's due-by is fixed
 *  from them when it is created, ahead of their grade's and the sheet's terms. A person may have a contact
 *  (stored trimmed and lower-cased; blank for none), shown on their row; another person's contact is refused.
 *  The editor remembers the version of the person it loaded; when someone else has saved them since,
 *  the save is refused (409) and the editor shows their current values, at their current version; any other
 *  refused edit closes the editor, leaving its error showing. Each person is a <tbody> so features can add
 *  cells and rows of their own to it (slots/defs/personRow). A quick-add bar takes a name and an amount
 *  and adds a draft claim for that person (adding them with grade A when the name is new) in one change. */
function People({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const [showRetired] = useShowRetired();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState<number | null>(null);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  const [gradeFrom, setGradeFrom] = useState('');
  const [terms, setTerms] = useState('');
  const [contact, setContact] = useState('');
  const [version, setVersion] = useState<number | null>(null);

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { id: number | null; name: string; grade: string; gradeFrom: string; terms: string; contact: string; version: number | null }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      return f.id === null
        ? postJson<Person>(base, { name: f.name, grade: f.grade, terms: f.terms, contact: f.contact })
        : postJson<Person>(`${base}/${f.id}`, { name: f.name, grade: f.grade, gradeFrom: f.gradeFrom, terms: f.terms, contact: f.contact, version: f.version });
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setTerms('');
      setContact('');
      setVersion(null);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: async (err, f) => {
      if (f.id === null) return;
      if (!(err instanceof HttpError && err.status === 409)) {
        // a refused edit closes the editor, its error still showing, so the form is back to adding
        setEditing(null);
        setName('');
        setGrade('A');
        setGradeFrom('');
        setTerms('');
        setContact('');
        setVersion(null);
        return;
      }
      const people = await queryClient.fetchQuery({
        queryKey: peopleKey(sheetId),
        queryFn: () => fetchPeople(sheetId),
        staleTime: 0,
      });
      const current = people.find((p) => p.id === f.id);
      if (current) {
        setName(current.name);
        setGrade(current.grade);
        setTerms(current.terms === null ? '' : String(current.terms));
        setContact(current.contact ?? '');
        setVersion(current.version);
      }
    },
  });

  const [quickName, setQuickName] = useState('');
  const [quickAmount, setQuickAmount] = useState('');
  const quickOnce = useSingleFlight();
  const quick = useMutation({
    mutationFn: (f: { name: string; amount: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick`, f),
    onSuccess: async () => {
      setQuickName('');
      setQuickAmount('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });

  const openEditor = (p: Person) => {
    save.reset();
    setEditing(p.id);
    setName(p.name);
    setGrade(p.grade);
    setGradeFrom('');
    setTerms(p.terms === null ? '' : String(p.terms));
    setContact(p.contact ?? '');
    setVersion(p.version);
  };

  const cancel = () => {
    save.reset();
    setEditing(null);
    setName('');
    setGrade('A');
    setGradeFrom('');
    setTerms('');
    setContact('');
    setVersion(null);
  };

  return (
    <section data-testid="people">
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ id: editing, name, grade, gradeFrom, terms, contact, version });
          });
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          from{' '}
          <input
            type="date"
            data-testid="person-form-grade-from"
            value={gradeFrom}
            onChange={(e) => {
              setGradeFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Terms (business days){' '}
          <input
            data-testid="person-form-terms"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Contact{' '}
          <input
            data-testid="person-form-contact"
            value={contact}
            onChange={(e) => {
              setContact(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {save.isError && <p data-testid="person-form-error">{save.error.message}</p>}
      </form>
      <form
        data-testid="quick-add"
        onSubmit={(e) => {
          e.preventDefault();
          quickOnce(() => {
            quick.reset();
            return quick.mutateAsync({ name: quickName, amount: quickAmount });
          });
        }}
      >
        <label>
          Quick add: name{' '}
          <input
            data-testid="quick-name"
            value={quickName}
            onChange={(e) => {
              setQuickName(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <label>
          Amount{' '}
          <input
            data-testid="quick-amount"
            value={quickAmount}
            onChange={(e) => {
              setQuickAmount(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="quick-submit" disabled={quick.isPending}>
          Add draft claim
        </button>
        {quick.isError && <p data-testid="quick-error">{quick.error.message}</p>}
      </form>
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Contact</th>
            <PersonColumnHead.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        {(people.data ?? []).filter((p) => showRetired || !p.retiredFrom).map((p) => (
          <tbody key={p.id} data-testid={`person-row-${p.id}`}>
            <tr>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-terms">{p.terms ?? ''}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => openEditor(p)}>
                  Edit
                </button>
              </td>
            </tr>
            <PersonDetail.Slot sheetId={sheetId} personId={p.id} />
          </tbody>
        ))}
      </table>
      {people.isError && <p data-testid="people-error">{people.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({
  order: 10,
  Component: ({ sheetId }) => <People sheetId={sheetId} />,
});

